create table if not exists public.schoolpro_health_records(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,student_id uuid not null references public.schoolpro_students(id) on delete cascade,recorded_at timestamptz not null default now(),complaint text not null,assessment text,treatment text,disposition text,recorded_by uuid references auth.users(id),created_at timestamptz not null default now());
create table if not exists public.schoolpro_academic_documents(id uuid primary key default gen_random_uuid(),school_id uuid not null references public.schoolpro_schools(id) on delete cascade,student_id uuid not null references public.schoolpro_students(id) on delete cascade,document_type text not null check(document_type in('id_card','certificate','transcript')),title text not null,session text,serial_number text not null default ('DOC-'||upper(substr(replace(gen_random_uuid()::text,'-',''),1,12))),issued_at timestamptz,issued_by uuid references auth.users(id),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),unique(school_id,serial_number));
alter table public.schoolpro_health_records enable row level security;alter table public.schoolpro_academic_documents enable row level security;
drop policy if exists health_school_staff on public.schoolpro_health_records;create policy health_school_staff on public.schoolpro_health_records for all to authenticated using(public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('nurse','counsellor','head_teacher','administrator','proprietor'))) with check(public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('nurse','counsellor','head_teacher','administrator','proprietor')));
drop policy if exists academic_documents_staff on public.schoolpro_academic_documents;create policy academic_documents_staff on public.schoolpro_academic_documents for all to authenticated using(public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('registrar','exam_officer','head_teacher','administrator','proprietor'))) with check(public.schoolpro_member_can_manage(school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=school_id and m.user_id=auth.uid() and m.role::text in('registrar','exam_officer','head_teacher','administrator','proprietor')));
create or replace function public.schoolpro_subscription_entitlements(p_school uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.schoolpro_subscriptions;begin if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid())) then raise exception 'Not authorized';end if;select * into s from public.schoolpro_subscriptions where school_id=p_school order by updated_at desc limit 1;if s.id is null or s.status not in('active','trial') then return jsonb_build_object('active',false,'tier','none','website',false,'cbt',false,'advanced_reports',false,'custom_branding',false);end if;return jsonb_build_object('active',true,'tier',s.tier,'website',true,'cbt',s.tier in('professional','premium','enterprise'),'advanced_reports',s.tier in('premium','enterprise'),'custom_branding',s.tier in('premium','enterprise'),'customization_level',s.customization_level);end$$;revoke all on function public.schoolpro_subscription_entitlements(uuid) from public,anon;grant execute on function public.schoolpro_subscription_entitlements(uuid) to authenticated;